#!/usr/bin/env python3
"""Reconcile a batch of payment transactions from a CSV file."""
import json
import re
import sys
from datetime import datetime
from decimal import Decimal, InvalidOperation

# Amount: digits with optional decimal part of 1 or 2 digits
AMOUNT_RE = re.compile(r"\d+(?:\.\d{1,2})?")
STATUSES = {"SUCCESS", "FAILED", "PENDING"}


def parse_timestamp(value: str):
    """Parse an ISO‑8601 timestamp with Z or offset.
    Returns an aware datetime or None if invalid.
    """
    # Handle UTC "Z" suffix
    if value.endswith('Z'):
        value = value[:-1] + '+00:00'
    try:
        ts = datetime.fromisoformat(value)
    except ValueError:
        return None
    if ts.tzinfo is None:
        return None
    return ts


def parse_row(line: str):
    """Parse a CSV line. Returns (tx_id, timestamp, amount, status) or None if malformed."""
    fields = line.split(',')
    if len(fields) != 4 or any(f == '' for f in fields):
        return None
    tx_id, timestamp, amount_str, status = fields
    ts = parse_timestamp(timestamp)
    if ts is None:
        return None
    if not AMOUNT_RE.fullmatch(amount_str):
        return None
    try:
        amount = Decimal(amount_str)
    except InvalidOperation:
        return None
    if status not in STATUSES:
        return None
    return tx_id, ts, amount, status


def reconcile(path: str):
    latest = {}
    with open(path, encoding='utf-8') as f:
        # Skip header line
        next(f, None)
        for line in f:
            line = line.rstrip('\n')
            row = parse_row(line)
            if row is None:
                print(f"skipping malformed row: {line!r}", file=sys.stderr)
                continue
            tx_id = row[0]
            # Keep the row with the most recent timestamp
            if tx_id not in latest or row[1] > latest[tx_id][1]:
                latest[tx_id] = row

    total = Decimal('0')
    valid_count = 0
    failed_count = 0
    for _, _, amount, status in latest.values():
        if status == 'SUCCESS':
            total += amount
            valid_count += 1
        elif status == 'FAILED':
            failed_count += 1
        # PENDING does not affect counts

    # Round to two decimal places (banker's rounding is fine for this spec)
    total = total.quantize(Decimal('0.01'))
    return {
        "total_valid_amount": float(total),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }


def main():
    if len(sys.argv) != 2:
        print("usage: reconcile.py <input.csv>", file=sys.stderr)
        sys.exit(2)
    result = reconcile(sys.argv[1])
    print(json.dumps(result))


if __name__ == "__main__":
    main()
